<script setup lang="ts">
import { ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api'
import { useListBackLocation } from '../composables/listNavigation'
import type { Attachment, Product } from '../types'
import { emptyToolSettings, formatDate, productTitle } from '../utils'
import { useRecordEditor } from '../composables/recordEditor'
import AttributeEditor from '../components/AttributeEditor.vue'
import AttachmentList from '../components/AttachmentList.vue'
import CompanySelect from '../components/CompanySelect.vue'
import ToolFields from '../components/ToolFields.vue'
import RecordOptionSelect from '../components/RecordOptionSelect.vue'
import LinkManager from '../components/LinkManager.vue'
import RevisionPanel from '../components/RevisionPanel.vue'
import ConflictDialog from '../components/ConflictDialog.vue'
import RelatedRecipes from '../components/RelatedRecipes.vue'
const route = useRoute(); const router = useRouter(); const id = route.params.id as string; const tool = route.path.startsWith('/tools/'); const noun = tool ? '道具' : '商品'; const collection = tool ? 'tools' : 'products'; const showHistory = ref(false); const uploadBusy = ref(false)
const backTo = useListBackLocation(`/${collection}`)
const { record: product, loading, saving, error, remoteNotice, dirty, conflict, apply, load, save, useServer, mergeLatest } = useRecordEditor<Product>(`/${collection}/${id}`, item => ({ chinese_name: item.chinese_name, english_name: item.english_name, company_id: item.company_id, category: item.category, description: item.description, development_status: item.development_status, attributes: item.attributes.map(({ key,value,certainty }) => ({ key,value,certainty })), use_category: item.use_category, tool_settings: item.tool_settings }), item => ({ ...item, tool_settings: { ...emptyToolSettings(), ...item.tool_settings, sources: item.tool_settings?.sources || [] } }))
async function upload(images: File[]) { uploadBusy.value = true; error.value = ''; try { for (const file of images) { const data = new FormData(); data.append('product_id',id); data.append('file',file); data.append('client_id',crypto.randomUUID()); product.value?.attachments.push(await api<Attachment>('/attachments',{ method: 'POST', body: data })) } } catch (e) { error.value = (e as Error).message } finally { uploadBusy.value = false } }
async function deleteAttachment(attachmentID: string) { if (!confirm('删除这张图片？')) return; try { await api(`/attachments/${attachmentID}`,{ method: 'DELETE' }); if (product.value) product.value.attachments = product.value.attachments.filter(item => item.id !== attachmentID) } catch (e) { error.value = (e as Error).message } }
async function refreshLinks() { try { const latest = await api<Product>(`/${collection}/${id}`); if (product.value) product.value.links = latest.links } catch (e) { error.value = (e as Error).message } }
async function remove() { if (!product.value || !confirm(`将这个${noun}移入回收站？关联灵感与配方会保留。`)) return; try { await api(`/${collection}/${id}`,{ method: 'DELETE', body: JSON.stringify({ version: product.value.version }) }); apply(product.value as Product); await router.push(backTo.value) } catch (e) { error.value = (e as Error).message } }
</script>
<template><p v-if="loading" class="muted">读取中…</p><p v-else-if="!product" class="error-text">{{ error }}</p><template v-else><div class="page-heading"><div><RouterLink :to="backTo">← 返回{{ noun }}库</RouterLink><h1>{{ productTitle(product) }}</h1><p>创建于 {{ formatDate(product.created_at) }} · 版本 {{ product.version }}</p></div><div class="heading-actions"><button class="secondary" @click="showHistory = !showHistory">修改历史</button><button class="danger-button" @click="remove">移入回收站</button></div></div><p v-if="remoteNotice" class="ai-status">服务器上有新变更，保存时会展示差异。</p><div class="detail-layout"><div class="detail-main"><form class="panel record-form" @submit.prevent="save"><h2>当前{{ noun }}设定</h2><div class="field-inline"><label>{{ noun }}中文名<input v-model="product.chinese_name" maxlength="160" placeholder="可留空" /></label><label>{{ noun }}英文名<input v-model="product.english_name" maxlength="160" placeholder="可留空" /></label></div><div class="field"><span class="field-label">所属公司</span><CompanySelect v-model="product.company_id" :fallback="product.company" /><RouterLink v-if="product.company_id && !product.company_deleted" :to="`/companies/${product.company_id}`" class="company-detail-link">查看公司 →</RouterLink><small v-if="product.company_deleted" class="danger-text">公司已删除，请重新选择。</small></div><div class="field"><span class="field-label">{{ noun }}分类</span><RecordOptionSelect v-model="product.category" kind="categories" :label="`${noun}分类`" /></div><div class="field"><span class="field-label">制作状态</span><RecordOptionSelect v-model="product.development_status" kind="statuses" label="制作状态" :fallback="product.development_status_label" /></div><label>{{ noun }}描述<textarea v-model="product.description" rows="6" placeholder="外观、背景和其他设定可直接写在这里。"></textarea></label><ToolFields v-if="tool" v-model:category="product.use_category" v-model:settings="product.tool_settings" /><div class="field"><span class="field-label">动态属性</span><AttributeEditor v-model="product.attributes" /></div><p v-if="error" class="error-text" role="alert">{{ error }}</p><div class="form-actions"><button class="primary" :disabled="saving || !dirty">{{ saving ? '保存中…' : dirty ? '保存修改' : '已保存' }}</button><span v-if="dirty" class="muted">有未保存修改</span></div></form><section class="panel"><h2>{{ tool ? '道具图片' : '商品图片与包装' }}</h2><AttachmentList :items="product.attachments" :busy="uploadBusy" @upload="upload" @delete="deleteAttachment" /></section><RelatedRecipes :item-id="id" :item-category="product.category" :item-kind="product.item_kind" /><RevisionPanel v-if="showHistory" :kind="tool ? 'tool' : 'product'" :id="id" :version="product.version" @restored="load(true)" /></div><aside class="side-panel"><section class="panel"><h2>关联灵感</h2><LinkManager owner-type="product" :owner-id="id" :links="product.links || []" @changed="refreshLinks" /></section></aside></div><ConflictDialog v-if="conflict" :current="conflict.current" :submitted="conflict.submitted" @server="useServer" @merge="mergeLatest" @cancel="conflict = undefined" /></template></template>
